{"implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError('Missing segments or budget in case')
    if not isinstance(segments, list) or not isinstance(budget, int):
        raise ValueError('Invalid types for segments or budget')

    total_min = 0
    total_cap = 0
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError('Segment missing required field')
        total_min += s['minimum']
        total_cap += s['capacity']

    if budget < total_min:
        raise ValueError(f'Budget {budget} less than sum of minima {total_min}')
    if budget > total_cap:
        raise ValueError(f'Budget {budget} exceeds sum of capacities {total_cap}')

    n = len(segments)
    allocated = [s['minimum'] for s in segments]
    remaining = budget - total_min

    while remaining > 0:
        best_idx = -1
        best_value = -1.0
        for i, s in enumerate(segments):
            if allocated[i] < s['capacity']:
                # metric = importance / (next allocated position)
                metric = s['importance'] / (allocated[i] + 1.0)
                if metric > best_value:
                    best_value = metric
                    best_idx = i
                # tie break by original order; > already handles strict >
        if best_idx == -1:
            # should not happen because budget <= total_cap
            raise RuntimeError('No segment can accept more tokens')
        allocated[best_idx] += 1
        remaining -= 1

    allocations = []
    total_allocated = 0
    for i, s in enumerate(segments):
        allocations.append({'name': s['name'], 'allocated': allocated[i]})
        total_allocated += allocated[i]

    return {
        'allocations': allocations,
        'total_allocated': total_allocated
    }
